import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Quick筛选 strong candidates by t-test
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i], equal_var=False)
            # Approximate AUC using correlation with outcome
            corr_with_outcome = np.corrcoef(feats.x[:, i], feats.y)[0,1]
            auc = 0.5 + 0.5 * abs(corr_with_outcome)
            strong_candidates.append((fid, abs(t_stat), p_val, auc))

    # Sort by t-statistic then AUC
    strong_candidates.sort(key=lambda x: (-x[1], -x[3]))

    # Remove near-duplicates quickly
    keep = []
    used = set()
    for fid, t_stat, p_val, auc in strong_candidates:
        if fid in used:
            continue
        keep.append((fid, t_stat, p_val, auc))
        used.add(fid)

        # Check correlations with this feature
        for other_fid, _, _, _ in strong_candidates:
            if other_fid == fid or other_fid in used:
                continue
            col1 = feats.column(fid)
            col2 = feats.column(other_fid)
            if col1 < len(feats.x[0]) and col2 < len(feats.x[0]):
                try:
                    corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1]
                    if abs(corr) >= 0.6:
                        used.add(other_fid)
                except:
                    pass

    # Select top candidates for drivers
    drivers = tuple(fid for fid, _, _, _ in keep[:MAX_DRIVERS])

    # For columns, use all features with p < 0.05 or high AUC
    columns = []
    products = []
    loadings = {}

    # Add all significant features to columns
    for fid, t_stat, p_val, auc in keep:
        if p_val < 0.05 or auc > 0.55:
            columns.append(fid)

    # Create products for highly correlated pairs
    corr_pairs = []
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            if col1 < len(feats.x[0]) and col2 < len(feats.x[0]):
                try:
                    corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1]
                    if abs(corr) >= 0.6:
                        corr_pairs.append((fid1, fid2))
                except:
                    pass

    # Add products for correlated pairs
    for fid1, fid2 in corr_pairs:
        if fid1 in columns and fid2 in columns:
            products.append((fid1, fid2))

    # Simple loading for top features
    for i, fid in enumerate(columns[:5]):
        col_idx = feats.column(fid)
        if col_idx < len(feats.x[0]):
            diff = np.mean(feats.x[feats.y==1, col_idx]) - np.mean(feats.x[feats.y==0, col_idx])
            loadings[fid] = float(abs(diff))

    return Design(drivers=drivers, columns=tuple(columns), products=tuple(products), loadings=loadings)
